import "core-js/modules/es.array.push.js";
import "core-js/modules/es.set.difference.v2.js";
import "core-js/modules/es.set.intersection.v2.js";
import "core-js/modules/es.set.is-disjoint-from.v2.js";
import "core-js/modules/es.set.is-subset-of.v2.js";
import "core-js/modules/es.set.is-superset-of.v2.js";
import "core-js/modules/es.set.symmetric-difference.v2.js";
import "core-js/modules/es.set.union.v2.js";
import axios from 'axios';
export default {
  name: 'JsonMover',
  data() {
    return {
      jsonData: null,
      originalFileName: '',
      isLoading: false,
      progressMessage: '',
      // ==========================================
      // ⚠️ ！！！这两个地方必须改，千万不能忘！！！
      // ==========================================
      // 1. 填上你自己的图床域名（不要加末尾的斜杠）
      API_BASE_URL: 'https://aa705c78.cloudflare-imgbed-f35.pages.dev',
      // 2. 填上你在图床后台生成的 API Token
      API_TOKEN: '你的_API_TOKEN'
    };
  },
  methods: {
    handleFileUpload(event) {
      const file = event.target.files[0];
      if (!file) return;
      this.originalFileName = file.name;
      const reader = new FileReader();
      reader.onload = e => {
        try {
          this.jsonData = JSON.parse(e.target.result);
          this.progressMessage = '文件解析成功，可以开始搬运。';
        } catch (error) {
          this.progressMessage = 'JSON 文件格式错误！';
          this.jsonData = null;
        }
      };
      reader.readAsText(file);
    },
    async processJson() {
      if (!this.jsonData) return;
      this.isLoading = true;
      this.progressMessage = '开始处理...';
      const imageUrls = this.extractImageUrls(this.jsonData);
      const urlMap = {};
      this.progressMessage = `发现 ${imageUrls.length} 张图片，开始上传...`;
      for (let i = 0; i < imageUrls.length; i++) {
        const oldUrl = imageUrls[i];
        this.progressMessage = `正在上传第 ${i + 1}/${imageUrls.length} 张图片...`;
        try {
          const newUrl = await this.uploadImage(oldUrl);
          if (newUrl) {
            urlMap[oldUrl] = newUrl;
          }
        } catch (error) {
          console.error(`上传失败: ${oldUrl}`, error);
        }
      }
      this.progressMessage = '上传完成，正在生成新文件...';
      const newJsonData = this.replaceUrlsInJson(this.jsonData, urlMap);
      this.downloadJson(newJsonData, `moved_${this.originalFileName}`);
      this.isLoading = false;
      this.progressMessage = '搬运完成！新文件已开始下载。';
    },
    extractImageUrls(obj) {
      let urls = [];
      for (const key in obj) {
        if (typeof obj[key] === 'string' && (key === 'url' || key === 'src')) {
          if (obj[key].match(/\.(jpeg|jpg|gif|png|webp|svg)$/i)) {
            urls.push(obj[key]);
          }
        } else if (typeof obj[key] === 'object' && obj[key] !== null) {
          urls = urls.concat(this.extractImageUrls(obj[key]));
        }
      }
      return [...new Set(urls)];
    },
    async uploadImage(imageUrl) {
      const imageResponse = await axios.get(imageUrl, {
        responseType: 'blob'
      });
      const imageBlob = imageResponse.data;
      const formData = new FormData();
      const fileName = imageUrl.split('/').pop().split('?')[0] || `image_${Date.now()}.jpg`;
      formData.append('file', imageBlob, fileName);
      const uploadResponse = await axios.post(`${this.API_BASE_URL}/upload`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          'Authorization': `Bearer ${this.API_TOKEN}`
        }
      });
      if (uploadResponse.data && uploadResponse.data.data && uploadResponse.data.data.url) {
        return uploadResponse.data.data.url;
      }
      throw new Error('上传 API 返回格式不符');
    },
    replaceUrlsInJson(obj, urlMap) {
      const newObj = JSON.parse(JSON.stringify(obj));
      const traverse = currentObj => {
        for (const key in currentObj) {
          if (typeof currentObj[key] === 'string') {
            if (urlMap[currentObj[key]]) {
              currentObj[key] = urlMap[currentObj[key]];
            }
          } else if (typeof currentObj[key] === 'object' && currentObj[key] !== null) {
            traverse(currentObj[key]);
          }
        }
      };
      traverse(newObj);
      return newObj;
    },
    downloadJson(data, filename) {
      const blob = new Blob([JSON.stringify(data, null, 2)], {
        type: 'application/json'
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
  }
};